{
  "references": [
    {
      "id": "R1",
      "summary_ko": "여성이 채소를 썰다가 갑자기 가구를 옮기는 방으로 전환되는 어색한 점프 컷/화면 전환 오류."
    },
    {
      "id": "R2",
      "summary_ko": "여성이 옮기는 의자가 허공에서 갑자기 나타나며 다른 의자와 겹쳐 글리치를 일으킴."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조가 함께 변하여 형태 및 존재 변화 가능성이 감지된 측정 영역."
    },
    {
      "id": "C2",
      "summary_ko": "손으로 조작하는 도중 칼자루가 부자연스럽게 늘어나고 형태가 변형됨."
    },
    {
      "id": "C3",
      "summary_ko": "채소를 써는 동안 칼날이 왜곡되고 두께가 변하며 도마 위에서 흐려짐."
    },
    {
      "id": "C4",
      "summary_ko": "안락의자가 앞으로 밀릴 때 팔걸이와 등받이 쿠션이 비강체적으로 늘어나고 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적 대상이 없는 일반 측정 제안이므로 장면 전환 오류(R1)와의 직접 일치 여부를 단정할 수 없어 불확실합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 채소 썰기와 가구 이동 사이의 비연속적인 화면 전환 오류이며, C2는 칼자루의 형태 변형 오류로 대상과 결함이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 장면 간의 어색한 전환 문제이며, C3은 칼날 부위의 왜곡 및 두께 변화 현상으로 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "R1은 장면 점프 컷 문제이고, C4는 안락의자의 모핑 및 비강체 변형 문제로 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 형태 및 존재 변화 가능성을 언급하는 일반 측정 제안으로, 의자가 허공에서 나타나 다른 의자와 글리치를 일으키는 구체적 현상(R2)과 동일한지 확정할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 의자의 생성 및 충돌 글리치이며, C2는 칼자루의 형태 변형으로 대상과 결함이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R2는 이동되는 의자의 돌발 출현과 글리치이며, C3은 식칼 칼날의 왜곡 현상으로 서로 무관합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "R2는 의자가 갑자기 나타나 다른 의자와 충돌하는 결함인 반면, C4는 의자가 밀릴 때 쿠션과 팔걸이가 늘어나는 변형 결함으로 구체적인 이상 현상이 다릅니다."
    }
  ]
}
